'use strict';
// Test double for the browser driver, resolved exactly the way CI resolves
// playwright: the probe does createRequire(PLAYWRIGHT_DIR/noop.js) and then
// require('playwright').  Nothing here drives a real page; it models the two
// states the live investigation measured on GitHub Pages, and records every
// locator call with the timeout the probe passed it:
//
//   STUB_HYDRATED=1  the mounted render -- reactLiveAtClick=true,
//                    kbdCountAtClick=2, .DocSearch-Input exists and typing
//                    renders hits;
//   STUB_HYDRATED=0  the server render -- reactLiveAtClick=false,
//                    kbdCountAtClick=0: the button is clickable, the click is
//                    dropped because no handler is attached yet, and
//                    .DocSearch-Input has count 0, so filling it times out.
//
// The probe under test is the generated file; its control flow, its timeouts
// and its exit code are what the tests assert.
const { appendFileSync } = require('node:fs');

const HYDRATED = process.env.STUB_HYDRATED === '1';
const LOG = process.env.STUB_CALL_LOG;

function record(entry) {
  appendFileSync(LOG, JSON.stringify(entry) + '\n');
}

function timeoutError(op, opts) {
  const err = new Error(
    `locator.${op}: Timeout ${opts.timeout}ms exceeded.` +
      '\nCall log:\n  - waiting for locator to be visible'
  );
  return err;
}

function locator(sel) {
  const api = {
    first: () => api,
    waitFor: async (opts = {}) => {
      record({ sel, op: 'waitFor', timeout: opts.timeout });
      if (sel === '.DocSearch-Button-Keys kbd' && !HYDRATED) throw timeoutError('waitFor', opts);
    },
    click: async (opts = {}) => {
      // The measured failing run: the click itself resolves; nothing happens.
      record({ sel, op: 'click', timeout: opts.timeout });
    },
    fill: async (value, opts = {}) => {
      record({ sel, op: 'fill', timeout: opts.timeout, value });
      if (sel === '.DocSearch-Input' && !HYDRATED) throw timeoutError('fill', opts);
    },
    count: async () => 5,
    innerText: async () => 'No results match your query',
  };
  return api;
}

module.exports = {
  chromium: {
    launch: async () => ({
      newPage: async () => ({
        on: () => {},
        goto: async (url, opts = {}) => {
          record({ sel: 'page', op: 'goto', timeout: opts.timeout });
        },
        locator: (sel) => locator(sel),
      }),
      close: async () => {
        record({ sel: 'browser', op: 'close' });
      },
    }),
  },
};
